import{_ as t,o as a,c as i,ah as s}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse('{"title":"Inscription gratuite et démonstration complète","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"admission/ecoles/inscription-et-demo.md","filePath":"src/admission/ecoles/inscription-et-demo.md"}'),o={name:"admission/ecoles/inscription-et-demo.md"};function r(n,e,l,u,d,c){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="inscription-gratuite-et-demonstration-complete" tabindex="-1">Inscription gratuite et démonstration complète <a class="header-anchor" href="#inscription-gratuite-et-demonstration-complete" aria-label="Permalink to &quot;Inscription gratuite et démonstration complète&quot;">​</a></h1><p>Découvrir ERA ne demande ni installation ni engagement : votre établissement peut créer son propre espace en ligne en quelques minutes, gratuitement et sans limite de durée, puis basculer vers une démonstration complète pour évaluer l&#39;ensemble de la solution avant de choisir une licence.</p><h2 id="creer-le-compte-de-votre-etablissement" tabindex="-1">Créer le compte de votre établissement <a class="header-anchor" href="#creer-le-compte-de-votre-etablissement" aria-label="Permalink to &quot;Créer le compte de votre établissement&quot;">​</a></h2><p>L&#39;inscription se fait depuis le site public d&#39;ERA, avec un formulaire très court :</p><ol><li>Le nom de votre établissement.</li><li>Votre nom.</li><li>Une adresse e-mail.</li><li>Un mot de passe.</li></ol><p>À la validation, deux choses sont créées automatiquement :</p><ul><li><strong>Un espace dédié à votre établissement</strong>, accessible à sa propre adresse (un sous-domaine construit à partir du nom de l&#39;établissement, par exemple <code>college-sainte-marie.&lt;domaine-era&gt;</code>).</li><li><strong>Votre compte administrateur</strong>, avec l&#39;adresse e-mail et le mot de passe que vous venez de choisir — c&#39;est le compte qui gère ensuite tout le reste (utilisateurs, structure, admissions...).</li></ul><p>Une page de confirmation vous rappelle l&#39;adresse de votre espace et vous permet de vous connecter directement. Gardez cette adresse : c&#39;est celle que votre équipe utilisera au quotidien.</p><h2 id="ce-que-couvre-l-offre-gratuite" tabindex="-1">Ce que couvre l&#39;offre gratuite <a class="header-anchor" href="#ce-que-couvre-l-offre-gratuite" aria-label="Permalink to &quot;Ce que couvre l&#39;offre gratuite&quot;">​</a></h2><p>L&#39;offre gratuite n&#39;est pas une version limitée de tout ERA : c&#39;est un seul module, pensé pour démarrer sans attendre —</p><ul><li>le <strong>formulaire public de candidature</strong>, que les familles peuvent utiliser dès le premier jour pour déposer un dossier ;</li><li>la <strong>file d&#39;attente des candidatures en lecture</strong>, pour suivre ce qui arrive.</li></ul><p>Le reste de l&#39;application (vie scolaire, finances, relations familles, tableau de bord de pilotage...) n&#39;est pas accessible dans cette offre. Si vous voulez voir l&#39;application dans son ensemble avant de vous engager, c&#39;est à ça que sert la démonstration complète décrite ci-dessous.</p><h2 id="activer-la-demonstration-complete" tabindex="-1">Activer la démonstration complète <a class="header-anchor" href="#activer-la-demonstration-complete" aria-label="Permalink to &quot;Activer la démonstration complète&quot;">​</a></h2><p>Une fois connecté à votre espace en offre gratuite, votre compte administrateur voit une invitation sur son tableau de bord pour activer une démonstration complète : elle débloque temporairement tous les pôles d&#39;ERA, sans engagement, pour évaluer la solution en conditions réelles avant de choisir une licence.</p><p>L&#39;activation elle-même — et la fin de vie de cette démo (durée, banderole d&#39;expiration proche, gel en lecture seule) — est détaillée du point de vue de l&#39;administrateur dans <a href="/era-guide/guide/admin/demo-et-journal.html">Démo complète et journal d&#39;activité</a> ; ce guide-ci ne la duplique pas.</p><p>En résumé, ce qu&#39;il faut retenir avant de vous décider :</p><ul><li>La démonstration dure un nombre de jours fixe à partir de son activation.</li><li>Elle ne peut être activée qu&#39;une fois, depuis l&#39;offre gratuite — elle n&#39;est pas reconductible indéfiniment de votre propre initiative.</li><li>Une fois activée, elle ne peut être arrêtée avant terme que par l&#39;équipe edPage (voir <a href="/era-guide/admission/staff-edpage/">le panel interne edPage</a>), pas depuis votre tableau de bord.</li></ul><h2 id="ce-qui-se-passe-a-la-fin-de-la-demo" tabindex="-1">Ce qui se passe à la fin de la démo <a class="header-anchor" href="#ce-qui-se-passe-a-la-fin-de-la-demo" aria-label="Permalink to &quot;Ce qui se passe à la fin de la démo&quot;">​</a></h2><p>Si aucune licence n&#39;a été achetée avant la fin de la période de démonstration, l&#39;accès à votre espace passe automatiquement en <strong>lecture seule</strong> : vous pouvez toujours consulter vos données, mais plus les modifier. C&#39;est le même état qu&#39;atteindrait un compte dont la démo a été close manuellement par l&#39;équipe edPage.</p><p>Cet état de lecture seule n&#39;est pas définitif dans l&#39;immédiat, mais il n&#39;est pas non plus permanent : un <strong>délai de grâce</strong> vous est laissé pour choisir votre licence ou nous contacter. Passé ce délai sans action de votre part, l&#39;établissement — ses données comprises — est <strong>supprimé définitivement</strong>, sans possibilité de récupération.</p><p>Pour éviter d&#39;en arriver là, voir <a href="/era-guide/admission/ecoles/passage-licence.html">Passer à une licence</a> dès que vous êtes prêts à vous engager.</p>',21)])])}const v=t(o,[["render",r]]);export{m as __pageData,v as default};
